# t_090d6f3d: multilingual strong-signal type table (en + zh), the data the
# deterministic `_detect_type` regex pass reads. Data-driven on purpose —
# adding a language = adding a row here, NOT editing the detector (the
# "hardcoded-keyword maintainability" pain this card resolves).
#
# Fact is the DEFAULT and has NO pattern row: an item matching no strong-signal
# row is a fact. Precedence is FIXED preference > decision > task (the legacy
# English detector order) so existing English verdicts do not regress. Only
# unambiguous strong signals are listed — deliberately NO bare 需要/应该, so a
# plain CJK fact ("这个需求需要在下个迭代处理") stays a fact-miss that the
# budget-gated host-LLM fallback (spike-3) may upgrade, instead of being
# misrouted by a weak regex keyword.
_MEMORY_TYPE_REGEX = {
    "preference": [
        # English (legacy, unchanged)
        r"i prefer|i like|i don't like|i hate|i love|my preference is|prefer|always\s+\w|never\s+\w",
        # Chinese strong signals
        r"我更喜欢|我喜欢|我讨厌|我偏爱|我倾向|不喜欢|更喜欢|讨厌|偏好",
    ],
    "decision": [
        # English (legacy, unchanged)
        r"i decide|i choose|i will use|let's use|we decided|decision|choice|selection",
        # Chinese strong signals
        r"我决定|我选择|我选用|我们定|定下来|拍板|敲定|选定|决策|选用|定为|最终选",
    ],
    "task": [
        # English (legacy, unchanged)
        r"todo|to do|task|remember to|need to|should|must|have to",
        # Chinese strong signals (no bare 需要/应该 — see the comment above;
        # PLAN-type PRD §1.3: 裸"计划"已移除 — 它既可能是待办"我计划做X"(task)
        # 也可能是"实施计划"(plan)，太弱会跟 plan 抢行；plan 的"实施计划"
        # 强信号归 plan，task 保留更明确的待办/时间信号)
        r"待办|记得|别忘|不忘|要完成|打算|必须|在下周|在下月|下个月|周五前|下下周",
    ],
    "plan": [
        # PLAN-type PRD §1.3: structured multi-step execution sequence / PRD /
        # ordered repair plan with a clear done-when criterion. Distinct from a
        # single atomic task. Placed AFTER task in the fixed precedence so a
        # content matching both task and plan strong signals lands task first
        # (task's "需要/待办" words are common inside plans; only genuinely
        # step-ordered / roadmap / PRD content escalates to plan).
        r"\bstep\s*\d\b|\bphase\s*\d\b|roadmap|implementation\s+plan"
        r"|fix\s+sequence|repair\s+plan|action\s+plan|execution\s+plan|multi-step"
        r"|\bprds?\b",
        r"步骤\s*\d|第\s*\d+\s*(步|阶段|点|条)|实施计划|修复步骤|执行计划"
        r"|多步|落地方案|PRD|路线图|分\s*\d+\s*(步|阶段)",
    ],
}

